/* Addressable Evidence visual system (straitjacket/docs/VISUAL-DESIGN.md):
   Square corners, 1px rules, semantic colour only, zero gradients/glow/glass. */
:root {
  --bg: #0D0F12;
  --ground: #15181D;
  --surface: #15181D;
  --surface2: #1C2026;
  --ink: #ECEAE3;
  --muted: #8D939A;
  --faint: #7D848D;
  --grid: #272C33;
  --blue: #6F96FF;
  --blue2: #263A68;
  --amber: #F0B429;
  --amber2: #58451D;
  --red: #FF7768;
  --red2: #542925;
  --green: #63D3A4;
  --panel: rgba(13, 15, 18, 0.94);

  /* Framing offsets read by stage.js on resize */
  --frame-x: 0.21;
  --frame-y: 0;
  --frame-fit: 1.08;
  --progress: 0;

  --font-display: 'Space Grotesk Variable', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --font-sans: 'Inter Variable', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --font-mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, monospace;

  color-scheme: dark;
}

* {
  box-sizing: border-box;
  border-radius: 0;
}

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--ink);
}

body {
  font: 15px/1.55 var(--font-sans);
  overflow-x: clip;
  -webkit-font-smoothing: antialiased;
}

/* Fixed architectural top instrument bar */
.topbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 48px;
  background: var(--bg);
  border-bottom: 1px solid var(--grid);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  z-index: 20;
}

.topbar-left, .topbar-right {
  display: flex;
  align-items: center;
  gap: 14px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--ink);
  text-decoration: none;
  font: 700 13px/1 var(--font-display);
  letter-spacing: 0.12em;
}

.version-tag {
  font: 400 11px/1 var(--font-mono);
  color: var(--muted);
  border: 1px solid var(--grid);
  padding: 4px 7px;
  background: var(--surface);
}

.chapter-dots {
  display: flex;
  align-items: center;
  gap: 4px;
}

.chapter-dots .dot {
  font: 700 11px/1 var(--font-mono);
  color: var(--muted);
  text-decoration: none;
  padding: 6px 8px;
  border: 1px solid transparent;
  transition: color 0.15s ease, border-color 0.15s ease, background-color 0.15s ease;
}

.chapter-dots .dot:hover {
  color: var(--ink);
  border-color: var(--grid);
}

.chapter-dots .dot.is-active {
  color: var(--amber);
  border-color: var(--amber);
  background: var(--surface);
}

.step-readout {
  font: 700 11px/1 var(--font-mono);
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

#step-num {
  color: var(--ink);
}

.docs-link {
  font: 700 12px/1 var(--font-mono);
  color: var(--blue);
  text-decoration: none;
  border: 1px solid var(--blue);
  padding: 6px 11px;
  background: var(--surface);
}

.docs-link:hover {
  background: var(--blue2);
  color: var(--ink);
}

.progress-rail {
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  height: 2px;
  background: transparent;
}

.progress-fill {
  height: 100%;
  width: calc(var(--progress) * 100%);
  background: var(--blue);
}

/* 3D canvas */
#stage {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100vh;
  height: 100lvh;
  display: block;
  z-index: 0;
}

/* Typography */
h1, h2 {
  font-family: var(--font-display);
  font-weight: 700;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  line-height: 1.08;
  margin: 0 0 0.55em;
  color: var(--ink);
}

h1 { font-size: clamp(1.75rem, 3vw, 2.55rem); }
h2 { font-size: clamp(1.35rem, 2.2vw, 1.95rem); }

p {
  margin: 0 0 0.85em;
  color: #D2D0C8;
}

code {
  font-family: var(--font-mono);
  font-size: 0.88em;
  color: var(--ink);
  background: var(--surface2);
  padding: 1px 4px;
}

.kicker {
  font: 700 11px/1.2 var(--font-mono);
